import { Dimensions, StyleSheet } from 'react-native';

const { width } = Dimensions.get('window');

export const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: '#F5F6F7',
    },
    // 顶部核心筛选头容器
    headerContainer: {
        backgroundColor: '#fff',
        paddingBottom: 5,
        borderBottomWidth: StyleSheet.hairlineWidth,
        borderBottomColor: '#EEE',
    },
    // 整个搜索栏所在的行
    searchBarContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        paddingHorizontal: 12,
        paddingVertical: 10,
        backgroundColor: '#fff',
    },
    // 返回按钮
    backButton: {
        width: 30, // 固定宽度防止抖动
        justifyContent: 'center',
    },
    backIcon: {
        fontSize: 22,
        color: '#333',
    },
    // 胶囊搜索框主体 - 关键：flex: 1 保证它不超出屏幕
    searchMainContent: {
        flex: 1,
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#F2F4F7', 
        borderRadius: 25,          
        paddingHorizontal: 12,
        paddingVertical: 4,
    },
    // 城市
    cityText: {
        fontSize: 15,
        fontWeight: 'bold',
        color: '#333',
        marginRight: 8,
    },
    // 住离日期垂直容器
    dateVerticalContainer: {
        marginRight: 6,
        justifyContent: 'center',
    },
    dateRow: {
        flexDirection: 'row',
        alignItems: 'center',
        lineHeight: 12,
    },
    dateLabel: {
        fontSize: 9,
        color: '#999',
        marginRight: 2,
    },
    dateValue: {
        fontSize: 10,
        color: '#3388FF', 
        fontWeight: '500',
    },
    // 几晚
    nightCountText: {
        fontSize: 10,
        color: '#666',
        marginRight: 8,
    },
    // 竖向分割线
    verticalDivider: {
        width: 1,
        height: 14,
        backgroundColor: '#DDD',
        marginRight: 8,
    },
    // 关键字搜索区域
    keywordContainer: {
        flex: 1, // 占据胶囊内剩余所有空间
        flexDirection: 'row',
        alignItems: 'center',
    },
    searchIcon: {
        fontSize: 12,
        marginRight: 4,
    },
    keywordPlaceholder: {
        fontSize: 12,
        color: '#999',
        flex: 1,
    },

    // 筛选Tab栏
    filterRow: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        paddingVertical: 12,
        backgroundColor: '#fff',
    },
    filterItem: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    filterText: {
        fontSize: 14,
        color: '#666',
    },
    arrowIcon: {
        fontSize: 10,
        marginLeft: 4,
        color: '#999',
    },

    // 酒店列表卡片
    hotelItem: {
        flexDirection: 'row',
        backgroundColor: '#fff',
        marginHorizontal: 12,
        marginTop: 12,
        borderRadius: 12,
        padding: 12,
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.05,
        shadowRadius: 5,
        elevation: 2,
    },
    hotelImage: {
        width: 100,
        height: 130,
        borderRadius: 8,
    },
    infoArea: {
        flex: 1,
        marginLeft: 12,
        justifyContent: 'space-between',
    },
    hotelName: {
        fontSize: 16,
        fontWeight: 'bold',
        color: '#333',
    },
    scoreRow: {
        flexDirection: 'row',
        alignItems: 'center',
        marginTop: 4,
    },
    scoreText: {
        fontSize: 14,
        color: '#007AFF',
        fontWeight: 'bold',
    },
    commentText: {
        fontSize: 12,
        color: '#666',
        marginLeft: 8,
    },
    addressText: {
        fontSize: 12,
        color: '#999',
        marginTop: 4,
    },
    tagRow: {
        flexDirection: 'row',
        flexWrap: 'wrap',
        marginTop: 8,
    },
    hotelTag: {
        backgroundColor: '#E8F3FF',
        paddingHorizontal: 6,
        paddingVertical: 2,
        borderRadius: 4,
        marginRight: 6,
        marginBottom: 4,
    },
    hotelTagText: {
        fontSize: 10,
        color: '#007AFF',
    },
    priceContainer: {
        flexDirection: 'row',
        alignItems: 'baseline',
        justifyContent: 'flex-end',
    },
    priceSymbol: {
        fontSize: 12,
        color: '#FF5A5F',
        fontWeight: 'bold',
    },
    priceText: {
        fontSize: 20,
        color: '#FF5A5F',
        fontWeight: 'bold',
    },
    priceUnit: {
        fontSize: 11,
        color: '#999',
        marginLeft: 2,
    },
    footerLoading: {
        paddingVertical: 20,
        alignItems: 'center',
    }
});
